// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Trigger a full or incremental re-index
	// (POST /admin/reindex)
	PostAdminReindex(ctx context.Context, request PostAdminReindexRequestObject) (PostAdminReindexResponseObject, error)
	// Report the migration runner state
	// (GET /admin/status)
	GetAdminStatus(ctx context.Context, request GetAdminStatusRequestObject) (GetAdminStatusResponseObject, error)
	// Upload an attachment to a note's attachments/ directory (ATTACH-01..04).
	// (POST /attachments/{noteId})
	CreateAttachment(ctx context.Context, request CreateAttachmentRequestObject) (CreateAttachmentResponseObject, error)
	// Stream an attachment file (ATTACH-05/06; path-traversal hardened).
	// (GET /attachments/{noteId}/{filename})
	GetAttachment(ctx context.Context, request GetAttachmentRequestObject) (GetAttachmentResponseObject, error)
	// Read user configuration
	// (GET /config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// Replace user configuration (whole-document)
	// (PUT /config)
	PutConfig(ctx context.Context, request PutConfigRequestObject) (PutConfigResponseObject, error)
	// Get-or-create today's daily note (DAILY-01..03).
	// (GET /daily-notes/{date})
	GetDailyNote(ctx context.Context, request GetDailyNoteRequestObject) (GetDailyNoteResponseObject, error)
	// Delete a non-markdown file under notes/ (UAT-4 R7b / Plan 07-38).
	// (DELETE /files)
	DeleteFile(ctx context.Context, request DeleteFileRequestObject) (DeleteFileResponseObject, error)
	// Stream any file under the notes vault by relative path (UAT-3 R7 / Plan 07-32a).
	// (GET /files)
	GetFile(ctx context.Context, request GetFileRequestObject) (GetFileResponseObject, error)
	// Upload an OS file into the notes/ tree at the specified directory (UAT-3 N2 / Plan 07-34).
	// (POST /files)
	CreateFile(ctx context.Context, request CreateFileRequestObject) (CreateFileResponseObject, error)
	// Rename / move a non-markdown file under notes/ (UAT-4 R7b / Plan 07-38).
	// (POST /files/move)
	PostFileMove(ctx context.Context, request PostFileMoveRequestObject) (PostFileMoveResponseObject, error)
	// Delete a folder (TREE-06) — non-empty requires recursive=true
	// (DELETE /folders)
	DeleteFolder(ctx context.Context, request DeleteFolderRequestObject) (DeleteFolderResponseObject, error)
	// Create a folder (TREE-04)
	// (POST /folders)
	PostFolders(ctx context.Context, request PostFoldersRequestObject) (PostFoldersResponseObject, error)
	// Rename or move a folder (TREE-05, TREE-07)
	// (POST /folders/move)
	PostFolderMove(ctx context.Context, request PostFolderMoveRequestObject) (PostFolderMoveResponseObject, error)
	// List subdirectories of an absolute path (UAT-2
	// (GET /fs/list)
	GetFsList(ctx context.Context, request GetFsListRequestObject) (GetFsListResponseObject, error)
	// Create a directory at an absolute path (folder-picker "New folder")
	// (POST /fs/mkdir)
	PostFsMkdir(ctx context.Context, request PostFsMkdirRequestObject) (PostFsMkdirResponseObject, error)
	// Revoke MCP write access for a folder (D-17)
	// (DELETE /mcp/grants)
	DeleteMcpGrant(ctx context.Context, request DeleteMcpGrantRequestObject) (DeleteMcpGrantResponseObject, error)
	// List all MCP write grants (MCP-01)
	// (GET /mcp/grants)
	GetMcpGrants(ctx context.Context, request GetMcpGrantsRequestObject) (GetMcpGrantsResponseObject, error)
	// Grant (or upgrade) MCP write access for a folder (MCP-01, D-17)
	// (POST /mcp/grants)
	PostMcpGrant(ctx context.Context, request PostMcpGrantRequestObject) (PostMcpGrantResponseObject, error)
	// List all indexed notes (metadata only)
	// (GET /notes)
	GetNotes(ctx context.Context, request GetNotesRequestObject) (GetNotesResponseObject, error)
	// Create a new note (TREE-03)
	// (POST /notes)
	PostNotes(ctx context.Context, request PostNotesRequestObject) (PostNotesResponseObject, error)
	// Lookup a note by its relative path (D-30 deep-link fallback)
	// (GET /notes/by-path)
	GetNoteByPath(ctx context.Context, request GetNoteByPathRequestObject) (GetNoteByPathResponseObject, error)
	// Search note titles for wiki-link autocomplete (LINKS-06 / D-13)
	// (GET /notes/search-titles)
	GetNotesSearchTitles(ctx context.Context, request GetNotesSearchTitlesRequestObject) (GetNotesSearchTitlesResponseObject, error)
	// Delete a note by UUID (TREE-06)
	// (DELETE /notes/{id})
	DeleteNoteById(ctx context.Context, request DeleteNoteByIdRequestObject) (DeleteNoteByIdResponseObject, error)
	// Read a note by UUID
	// (GET /notes/{id})
	GetNoteById(ctx context.Context, request GetNoteByIdRequestObject) (GetNoteByIdResponseObject, error)
	// Replace the content of a note by UUID
	// (PUT /notes/{id})
	PutNoteById(ctx context.Context, request PutNoteByIdRequestObject) (PutNoteByIdResponseObject, error)
	// List notes that link to this note (LINKS-08 / D-27)
	// (GET /notes/{id}/backlinks)
	GetNoteBacklinks(ctx context.Context, request GetNoteBacklinksRequestObject) (GetNoteBacklinksResponseObject, error)
	// Rename or move a note (TREE-05, TREE-07)
	// (POST /notes/{id}/move)
	PostNoteMove(ctx context.Context, request PostNoteMoveRequestObject) (PostNoteMoveResponseObject, error)
	// Reveal a note path in the host OS file manager (SHARE-01)
	// (POST /reveal)
	PostReveal(ctx context.Context, request PostRevealRequestObject) (PostRevealResponseObject, error)
	// FTS5 full-text search over note bodies and tag values (SEARCH-01..04).
	// (GET /search)
	SearchNotes(ctx context.Context, request SearchNotesRequestObject) (SearchNotesResponseObject, error)
	// Submit the first-run wizard (INSTALL-07, D-10)
	// (POST /setup)
	PostSetup(ctx context.Context, request PostSetupRequestObject) (PostSetupResponseObject, error)
	// First-run wizard status (INSTALL-07, D-04)
	// (GET /setup/status)
	GetSetupStatus(ctx context.Context, request GetSetupStatusRequestObject) (GetSetupStatusResponseObject, error)
	// Debounced wizard-side validation of a proposed data directory (D-08)
	// (POST /setup/validate-data-dir)
	PostSetupValidateDataDir(ctx context.Context, request PostSetupValidateDataDirRequestObject) (PostSetupValidateDataDirResponseObject, error)
	// List all tags with note counts (TAGS-03)
	// (GET /tags)
	GetTags(ctx context.Context, request GetTagsRequestObject) (GetTagsResponseObject, error)
	// Remove a tag from all notes (TAGS-07 / D-24)
	// (DELETE /tags/{name})
	DeleteTag(ctx context.Context, request DeleteTagRequestObject) (DeleteTagResponseObject, error)
	// Rename a tag across all notes (TAGS-06 / D-23)
	// (PUT /tags/{name})
	PutTag(ctx context.Context, request PutTagRequestObject) (PutTagResponseObject, error)
	// List notes carrying a specific tag (TAGS-04 / D-02)
	// (GET /tags/{name}/notes)
	GetTagNotes(ctx context.Context, request GetTagNotesRequestObject) (GetTagNotesResponseObject, error)
	// Return the full folder/file hierarchy under notes/ (TREE-01)
	// (GET /tree)
	GetTree(ctx context.Context, request GetTreeRequestObject) (GetTreeResponseObject, error)
	// Create a new vault inside a chosen folder; runs migrations; registers in recent_vaults
	// (POST /vault/create)
	PostVaultCreate(ctx context.Context, request PostVaultCreateRequestObject) (PostVaultCreateResponseObject, error)
	// Get the currently open vault (or null if none)
	// (GET /vault/current)
	GetVaultCurrent(ctx context.Context, request GetVaultCurrentRequestObject) (GetVaultCurrentResponseObject, error)
	// Remove an entry from recent_vaults (idempotent; does NOT delete the vault on disk)
	// (POST /vault/forget)
	PostVaultForget(ctx context.Context, request PostVaultForgetRequestObject) (PostVaultForgetResponseObject, error)
	// Open an existing vault (must already contain a .jasper/ directory)
	// (POST /vault/open)
	PostVaultOpen(ctx context.Context, request PostVaultOpenRequestObject) (PostVaultOpenResponseObject, error)
	// Get the recent_vaults list (newest-first; missing entries included with missing=true)
	// (GET /vault/recent)
	GetVaultRecent(ctx context.Context, request GetVaultRecentRequestObject) (GetVaultRecentResponseObject, error)
	// Hot-swap from the currently open vault to a target vault
	// (POST /vault/switch)
	PostVaultSwitch(ctx context.Context, request PostVaultSwitchRequestObject) (PostVaultSwitchResponseObject, error)
	// WebSocket endpoint (HTTP/1.1 Upgrade)
	// (GET /ws)
	GetApiV1Ws(ctx context.Context, request GetApiV1WsRequestObject) (GetApiV1WsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// PostAdminReindex operation middleware
func (sh *strictHandler) PostAdminReindex(w http.ResponseWriter, r *http.Request) {
	var request PostAdminReindexRequestObject

	var body PostAdminReindexJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		if !errors.Is(err, io.EOF) {
			sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
			return
		}
	} else {
		request.Body = &body
	}

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.PostAdminReindex(ctx, request.(PostAdminReindexRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "PostAdminReindex")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(PostAdminReindexResponseObject); ok {
		if err := validResponse.VisitPostAdminReindexResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

